package br.com.weg.workshop.post.domain;
import br.com.weg.workshop.preference.domain.Category; import br.com.weg.workshop.user.domain.UserEntity; import br.com.weg.workshop.workshop.domain.Workshop; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="post",schema="workshop") public class Post { @Id private UUID id; @Column(nullable=false) private String title; @Column(nullable=false,columnDefinition="TEXT") private String content; private String image; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="workshop_id") private Workshop workshop; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="category_id") private Category category; @Enumerated(EnumType.STRING) @Column(nullable=false) private PostStatus status; @Column(nullable=false) private boolean highlight; private Instant scheduledAt; private Instant publishedAt; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="created_by",nullable=false) private UserEntity createdBy; @Column(nullable=false,updatable=false) private Instant createdAt; @Column(nullable=false) private Instant updatedAt; protected Post(){} public static Post create(String title,String content,String image,Workshop workshop,Category category,boolean highlight,UserEntity creator){Post p=new Post();p.id=UUID.randomUUID();p.title=title;p.content=content;p.image=image;p.workshop=workshop;p.category=category;p.highlight=highlight;p.createdBy=creator;p.status=PostStatus.DRAFT;p.createdAt=Instant.now();p.updatedAt=p.createdAt;return p;} public void update(String title,String content,String image,Workshop workshop,Category category,boolean highlight){this.title=title;this.content=content;this.image=image;this.workshop=workshop;this.category=category;this.highlight=highlight;updatedAt=Instant.now();} public void schedule(Instant at){status=PostStatus.SCHEDULED;scheduledAt=at;updatedAt=Instant.now();} public void publish(){status=PostStatus.PUBLISHED;scheduledAt=null;publishedAt=Instant.now();updatedAt=publishedAt;} public void archive(){status=PostStatus.ARCHIVED;updatedAt=Instant.now();} public UUID getId(){return id;} public String getTitle(){return title;} public String getContent(){return content;} public String getImage(){return image;} public Workshop getWorkshop(){return workshop;} public Category getCategory(){return category;} public PostStatus getStatus(){return status;} public boolean isHighlight(){return highlight;} public Instant getScheduledAt(){return scheduledAt;} public Instant getPublishedAt(){return publishedAt;} public UserEntity getCreatedBy(){return createdBy;} public Instant getCreatedAt(){return createdAt;} public Instant getUpdatedAt(){return updatedAt;} }
